-- ====================================================================
-- SUPABASE POSTGRESQL SCHEMA FOR TIRUMALA TIRUPATI RESTAURANT
-- Run this in your Supabase Dashboard: SQL Editor -> New query -> Run
-- Project: https://tqpyykxucwndqwjnlmtz.supabase.co
-- ====================================================================

-- 1. CATEGORIES TABLE
CREATE TABLE IF NOT EXISTS public.categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    slug TEXT UNIQUE NOT NULL,
    time_slot TEXT DEFAULT 'all-day',
    description TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. MENU ITEMS TABLE
CREATE TABLE IF NOT EXISTS public.menu_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_slug TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    price NUMERIC(10,2) NOT NULL,
    offer_price NUMERIC(10,2),
    image_url TEXT NOT NULL,
    time_slot TEXT DEFAULT 'all-day',
    is_veg SMALLINT DEFAULT 1,
    is_daily_special SMALLINT DEFAULT 0,
    rating NUMERIC(3,2) DEFAULT 4.9,
    total_ratings INT DEFAULT 150,
    ingredients TEXT,
    allergens TEXT,
    calories INT,
    preparation_style TEXT,
    worship_significance TEXT,
    available SMALLINT DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. REVIEWS TABLE (With Attached Customer Photos & Auto-Replies)
CREATE TABLE IF NOT EXISTS public.reviews (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    menu_item_id BIGINT,
    dish_name TEXT DEFAULT 'Satvik Feast',
    user_name TEXT NOT NULL,
    user_email TEXT,
    user_mobile TEXT,
    rating INT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment TEXT NOT NULL,
    images JSONB DEFAULT '[]'::jsonb,
    likes_count INT DEFAULT 0,
    status TEXT DEFAULT 'approved',
    restaurant_reply JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. TABLE RESERVATIONS TABLE
CREATE TABLE IF NOT EXISTS public.table_reservations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reservation_code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    mobile TEXT NOT NULL,
    res_date TEXT NOT NULL,
    res_time TEXT NOT NULL,
    guests INT NOT NULL,
    seating_area TEXT DEFAULT 'Indoor Air Conditioned',
    special_requests TEXT DEFAULT 'None',
    status TEXT DEFAULT 'Confirmed',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. ORDERS TABLE
CREATE TABLE IF NOT EXISTS public.orders (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_number TEXT UNIQUE NOT NULL,
    user_name TEXT DEFAULT 'Devotee Guest',
    house_no TEXT NOT NULL,
    street TEXT NOT NULL,
    area TEXT NOT NULL,
    city TEXT DEFAULT 'Tirupati',
    pin_code TEXT DEFAULT '517501',
    primary_mobile TEXT,
    secondary_mobile TEXT NOT NULL,
    distance_km NUMERIC(5,2),
    grand_total NUMERIC(10,2) NOT NULL,
    payment_method TEXT DEFAULT 'UPI',
    order_status TEXT DEFAULT 'Order Confirmed',
    estimated_delivery_time TEXT DEFAULT '35-45 Minutes',
    items JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. USERS TABLE
CREATE TABLE IF NOT EXISTS public.users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    mobile TEXT,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT DEFAULT 'customer',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Drop unique constraint on mobile if it exists so duplicate phones don't violate constraint
ALTER TABLE IF EXISTS public.users DROP CONSTRAINT IF EXISTS users_mobile_key;

-- ENABLE ROW LEVEL SECURITY (RLS) & OPEN ACCESS POLICIES
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.menu_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.table_reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;

-- Allow public reads and inserts (idempotent with DROP POLICY IF EXISTS)
DROP POLICY IF EXISTS "Public Read Categories" ON public.categories;
CREATE POLICY "Public Read Categories" ON public.categories FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public Read Menu Items" ON public.menu_items;
CREATE POLICY "Public Read Menu Items" ON public.menu_items FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public Read Reviews" ON public.reviews;
CREATE POLICY "Public Read Reviews" ON public.reviews FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public Insert Reviews" ON public.reviews;
CREATE POLICY "Public Insert Reviews" ON public.reviews FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Public Update Reviews" ON public.reviews;
CREATE POLICY "Public Update Reviews" ON public.reviews FOR UPDATE USING (true);

DROP POLICY IF EXISTS "Public Read Table Reservations" ON public.table_reservations;
CREATE POLICY "Public Read Table Reservations" ON public.table_reservations FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public Insert Table Reservations" ON public.table_reservations;
CREATE POLICY "Public Insert Table Reservations" ON public.table_reservations FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Public Read Orders" ON public.orders;
CREATE POLICY "Public Read Orders" ON public.orders FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public Insert Orders" ON public.orders;
CREATE POLICY "Public Insert Orders" ON public.orders FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Public Read Users" ON public.users;
CREATE POLICY "Public Read Users" ON public.users FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public Insert Users" ON public.users;
CREATE POLICY "Public Insert Users" ON public.users FOR INSERT WITH CHECK (true);

