INSERT INTO public.reviews (id, dish_name, user_name, user_email, rating, comment, images, likes_count, status, restaurant_reply, created_at) VALUES (6, 'Ghee Masala Dosa', 'Kalyan Chakravarthy', '', 5, 'The Ven Pongal and Ghee Masala Dosa with drumstick sambar was absolutely top class!', '["/dosa.jpg"]'::jsonb, 0, 'approved', '{"text":"🙏 Namaste Kalyan Chakravarthy! We are overjoyed that you enjoyed our crispy deshi ghee dosas and soft cotton idlis with freshly ground coconut chutney and piping drumstick sambar. Freshness and pure ghee are our eternal promise to every pilgrim!","author":"Kanaparthi Akshay (Manager)","badge":"Operations Manager","replied_at":"2026-10-15T15:21:46.574Z"}'::jsonb, '2026-10-15T15:21:46.574Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reviews (id, dish_name, user_name, user_email, rating, comment, images, likes_count, status, restaurant_reply, created_at) VALUES (5, 'Srivari Maha Bhojanam', 'Ananya Sharma', 'ananya@tirupati.com', 5, 'The traditional banana leaf meal was blissful! Everything from the podi ghee rice to the payasam was divine.', '["/bhojanam.jpg","/table_2.jpg"]'::jsonb, 1, 'approved', '{"text":"🙏 Namaste Ananya Sharma! Srivari blessings to you and your family. We are thrilled that you relished our royal 18-item sacred Satvik Bhojanam served on the traditional banana leaf. Our kitchen adheres strictly to sacred temple recipes without onion or garlic. We look forward to serving you again on your next holy visit to Tirupati!","author":"Rachakonda Mithrakumar (Owner) & Chief Chef Koppula Koteshwar Rao","badge":"Temple Kitchen Management","replied_at":"2026-10-15T15:16:41.044Z"}'::jsonb, '2026-10-15T13:20:42.369Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reviews (id, dish_name, user_name, user_email, rating, comment, images, likes_count, status, restaurant_reply, created_at) VALUES (1, 'Ghee Masala Dosa & Cotton Idli', 'Ramesh Kumar', '', 5, 'Authentic Tirupati taste! The ghee idlis were divine and soft as cotton. The pure cow ghee masala dosa was delightfully crisp.', '["/dosa.jpg"]'::jsonb, 24, 'approved', '{"text":"🙏 Namaste Ramesh Kumar! We are overjoyed that you enjoyed our crispy deshi ghee dosas and soft cotton idlis with freshly ground coconut chutney and piping drumstick sambar. Freshness and pure ghee are our eternal promise to every pilgrim!","author":"Kanaparthi Akshay (Manager)","badge":"Operations Manager","replied_at":"2026-10-15T15:16:41.044Z"}'::jsonb, '2026-10-14T08:30:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reviews (id, dish_name, user_name, user_email, rating, comment, images, likes_count, status, restaurant_reply, created_at) VALUES (2, 'Srivari Maha Bhojanam', 'Srinivas Rao', '', 5, 'The Srivari Maha Bhojanam is a royal feast! Served on a real banana leaf with 18 sacred Satvik items. The ghee and sambar aroma made our Tirupati pilgrimage unforgettable.', '["/bhojanam.jpg","/table_2.jpg"]'::jsonb, 39, 'approved', '{"text":"🙏 Namaste Srinivas Rao! Srivari blessings to you and your family. We are thrilled that you relished our royal 18-item sacred Satvik Bhojanam served on the traditional banana leaf. Our kitchen adheres strictly to sacred temple recipes without onion or garlic. We look forward to serving you again on your next holy visit to Tirupati!","author":"Rachakonda Mithrakumar (Owner) & Chief Chef Koppula Koteshwar Rao","badge":"Temple Kitchen Management","replied_at":"2026-10-15T15:16:41.044Z"}'::jsonb, '2026-10-12T13:15:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reviews (id, dish_name, user_name, user_email, rating, comment, images, likes_count, status, restaurant_reply, created_at) VALUES (3, 'Tirupati Laddu Prasadam & Pongal', 'Padma Subrahmanyam', '', 5, 'The Tirupati Laddu prasadam has exact temple ghee aroma and Pachcha Karpooram taste. Blessed dining experience right near the bus stand.', '["/laddu.jpg","/pongal.jpg"]'::jsonb, 52, 'approved', '{"text":"🙏 Govinda Govinda, Padma Subrahmanyam! Thank you for your divine blessings. Our sacred Tirupati Laddu Prasadam is prepared using pure cow ghee, premium cashews, and Pachcha Karpooram, just like temple offerings. May Lord Venkateswara shower you with abundant health and happiness!","author":"Koppula Koteshwar Rao (Chief Chef)","badge":"Prasadam Department","replied_at":"2026-10-15T15:16:41.044Z"}'::jsonb, '2026-10-10T19:45:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reviews (id, dish_name, user_name, user_email, rating, comment, images, likes_count, status, restaurant_reply, created_at) VALUES (4, 'Temple Pulihora & Daddojanam', 'Venkatesh Ananth', '', 5, 'Exceptional temple cleanliness and spiritual hospitality. Pure Satvik without onion or garlic, just like Tirumala temple naivedyam.', '["/pulihora.jpg","/daddojanam.jpg"]'::jsonb, 19, 'approved', '{"text":"🙏 Dhanyavadalu Venkatesh Ananth! Cleanliness is next to godliness. Situated conveniently beside Tirupati bus stand, our goal is to offer weary travelers and pilgrims a serene, pristine, and spiritually uplifting dining haven. Thank you for your kind words!","author":"Kanaparthi Akshay (Manager)","badge":"Guest Hospitality","replied_at":"2026-10-15T15:16:41.044Z"}'::jsonb, '2026-10-08T12:20:00.000Z') ON CONFLICT (id) DO NOTHING;

